function rateLimit(clientIp) {
  const min = Math.floor(Date.now() / 60000);
  // 惰性清理过期条目，防内存膨胀
  if (rateMap.size > 4096) {
    for (const [k, e] of rateMap) { if (e.t !== min) rateMap.delete(k); }
  }
  const e = rateMap.get(clientIp);
  if (!e || e.t !== min) { rateMap.set(clientIp, { t: min, n: 1 }); return true; }
  if (e.n >= RATE_LIMIT_PER_MIN) return false;
  e.n += 1; return true;
}
// 尽力而为的定期清理（CF isolate 存活期间有效）
