// 进程内 KV 模拟 + Cloudflare KV 持久层（双层缓存）：
// 内存层负责热点秒回；真实 KV 层负责跨 isolate/冷启动持久化，
// 避免每次冷启动都回源 GitHub API（国内玩家体感"连不上/太卡"的主因）。
const kvMem = new Map();
let ENV = {}; // Node:由入口初始化(见文件尾)
function kvKey(key) { return JSON.stringify(key); }
async function kvGet(key) {
  const k = kvKey(key);
  const e = kvMem.get(k);
  if (e) {
    if (e.exp && Date.now() > e.exp) { kvMem.delete(k); }
    else return { value: e.val };
  }
  try {
    const ns = ENV && ENV.REALM_KV;
    if (ns) {
      const s = await kvWithTimeout(ns.get(k), 3000);
      if (s != null) {
        let v = null;
        try { v = JSON.parse(s); } catch (_) { v = s; }
        return { value: v };
      }
    }
  } catch (err) { console.error("KV get remote err", String(err)); }
  return { value: null };
}
async function kvSet(key, val, opts = {}) {
  const k = kvKey(key);
  kvMem.set(k, { exp: opts.expireIn ? Date.now() + opts.expireIn : 0, val });
  if (kvMem.size > 8192) { const now = Date.now(); for (const [x, e2] of kvMem) { if (e2.exp && now > e2.exp) kvMem.delete(x); } }
  try {
    const ns = ENV && ENV.REALM_KV;
    if (ns) {
      const ttl = opts.expireIn ? Math.max(60, Math.ceil(opts.expireIn / 1000)) : undefined;
      const putOpts = ttl ? { expirationTtl: ttl } : undefined;
      await kvWithTimeout(ns.put(k, JSON.stringify(val), putOpts), 3000);
    }
  } catch (err) { console.error("KV set remote err", String(err)); }
  return { ok: true };
}
async function kvDelete(key) {
  const k = kvKey(key);
  kvMem.delete(k);
  try {
    const ns = ENV && ENV.REALM_KV;
    if (ns) await kvWithTimeout(ns.delete(k), 3000);
  } catch (err) { console.error("KV delete remote err", String(err)); }
  return { ok: true };
}
// KV 操作统一加超时保险：KV 异常/未就绪时降级，绝不阻塞请求
function kvWithTimeout(p, ms = 15000) {
  return Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error("kv timeout")), ms))]);
}
const KV_CHUNK = 25_000;
async function kvSetBig(prefix, obj, ttl = 3_600_000) {
  try {
    await kvSet(prefix, obj, { expireIn: ttl });
  } catch (e) { console.error("KV setBig", prefix.join("/"), e); throw e; }
}
async function kvGetBig(prefix) {
  try {
    const r = await kvGet(prefix);
    return r && r.value != null ? r.value : null;
  } catch (e) { console.error("KV getBig", prefix.join("/"), e); throw e; }
}
async function kvDelPrefix(prefix) {
  try {
    const p = JSON.stringify(prefix);
    for (const k of [...kvMem.keys()]) { if (k === p || k.startsWith(p + ",")) kvMem.delete(k); }
    const ns = ENV && ENV.REALM_KV;
    if (ns) { try { await kvWithTimeout(ns.delete(p), 3000); } catch (err) { console.error("KV del remote err", String(err)); } }
  } catch (e) { console.error("KV del prefix", prefix, e); }
}
// GitHub API 请求封装：GET 结果缓存（内存 120 秒）；写操作成功后清空缓存保证一致性
const ghGetCache = new Map(); // method|path -> {ts, out}
async function ghJson(path, token, init = {}) {
  const L = await localDispatch(path, token, init, ghRemote);
  if (L) return L;
  return ghRemote(path, token, init);
}
async function ghRemote(path, token, init = {}) {
  const method = (init.method || "GET").toUpperCase();
  const key = method + "|" + path;
  if (method === "GET") {
    const hit = ghGetCache.get(key);
    if (hit && Date.now() - hit.ts < 30_000) return hit.out;
  }
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 15000);
  let r;
  try {
    r = await fetch(GH + path, {
      ...init,
      signal: ctrl.signal,
      headers: {
        Authorization: "Bearer " + token,
        Accept: "application/vnd.github+json",
        "User-Agent": "dc-food-lib/1.0 (DCTasteHelper cloud)",
        "X-GitHub-Api-Version": "2022-11-28",
        ...(init.headers || {}),
      },
    });
  } catch (e) {
    clearTimeout(t);
    console.error("GH FETCH ERR", path, String(e));
    return { status: 0, ok: false, data: null, err: String(e) };
  }
  clearTimeout(t);
  const text = await r.text();
  let d = null;
  try { d = JSON.parse(text); } catch { d = text; }
  const out = { status: r.status, ok: r.ok, data: d };
  // Node:回源成功后落盘本地(懒迁移),下次直接本地读
  if (method === "GET" && r.ok) { try { await localStoreRemote(path, d); } catch (e) { console.error("STORE REMOTE ERR " + path + " " + String(e)); } }
  if (method === "GET" && r.ok) {
    ghGetCache.set(key, { ts: Date.now(), out });
    if (ghGetCache.size > 512) { for (const k of ghGetCache.keys()) { if (ghGetCache.size <= 256) break; ghGetCache.delete(k); } }
  }
  if ((method === "PUT" || method === "DELETE") && r.ok) {
    ghGetCache.clear();
  }
  return out;
}

// base64 <-> utf8
function toB64(s) {
  const bytes = new TextEncoder().encode(s);
  let bin = "";
  const CH = 8192;
  for (let i = 0; i < bytes.length; i += CH) {
    bin += String.fromCharCode(...bytes.subarray(i, i + CH));
  }
  return btoa(bin);
}
function fromB64(s) {
  const bin = atob(s);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}

// 读仓库文件文本（存在返回 {sha, content}，不存在返回 null）——带 20 秒内存缓存
const ghCache = new Map(); // repo|path -> {ts, val}
async function ghRead(repo, path, token) {
  const key = repo + "|" + path;
  const hit = ghCache.get(key);
  if (hit && Date.now() - hit.ts < 15_000) return hit.val;
  const r = await ghJson(`/repos/${repo}/contents/${encodeURIComponent(path)}`, token);
  if (!r.ok) return null;
  const val = { sha: r.data.sha, content: fromB64(r.data.content) };
  ghCache.set(key, { ts: Date.now(), val });
  if (ghCache.size > 256) { for (const k of ghCache.keys()) { if (ghCache.size <= 128) break; ghCache.delete(k); } }
  return val;
}
// 写/删后主动失效缓存，保证读写一致
function ghInvalidate(repo, path) {
  ghCache.delete(repo + "|" + path);
}
// 写仓库文件（自动处理创建/更新）
async function ghWrite(repo, path, token, content, message) {
  const existing = await ghRead(repo, path, token);
  const body = {
    message,
    content: toB64(content),
  };
  if (existing) body.sha = existing.sha;
  const putR = await ghJson(`/repos/${repo}/contents/${encodeURIComponent(path)}`, token, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (putR.ok) ghInvalidate(repo, path);
  return putR;
}
// jsDelivr CDN 拉取公开仓文件原文（国内节点，秒级；失败返回 null）
async function jdRead(path) {
  try {
    const enc = path.split("/").map(encodeURIComponent).join("/");
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 8000);
    const r = await fetch("https://cdn.jsdelivr.net/gh/" + PUBLIC_REPO + "@main/" + enc, { signal: ctrl.signal });
    clearTimeout(t);
    if (!r.ok) return null;
    return await r.text();
  } catch (e) { console.error("JSDELIVR read", path, String(e)); return null; }
}
// 刷新 jsDelivr 缓存（音效更新/删除后调用，fire-and-forget）
function jdPurge(path) {
  fetch("https://purge.jsdelivr.net/gh/" + PUBLIC_REPO + "@main/" + path).catch(() => {});
}
// 删除仓库文件（不存在时返回 null）
async function ghDelete(repo, path, token, message) {
  const existing = await ghRead(repo, path, token);
  if (!existing) return null;
  const delR = await ghJson(`/repos/${repo}/contents/${encodeURIComponent(path)}`, token, {
    method: "DELETE",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ message: message || "delete", sha: existing.sha }),
  });
  if (delR.ok) ghInvalidate(repo, path);
  return delR;
}

async function sha256hex(s) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}
function genKey() {
  const b = new Uint8Array(16);
  crypto.getRandomValues(b);
  return Array.from(b).map((x) => x.toString(16).padStart(2, "0")).join("");
}
function validUuid(u) {
  return /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(u);
}
function validName(n) {
  return typeof n === "string" && n.length >= 1 && n.length <= 32 && /^[\w\u4e00-\u9fa5-]+$/.test(n);
}
// 登录信号三重校验
function verifyLoginProof(p, playerName) {
  if (!p || typeof p !== "object") return false;
  const mainOk = typeof p.main === "string" && p.main === DC_MAIN_SIGNAL;
  const nameOk = typeof p.name === "string" && p.name === `您好[DC]${playerName}！`;
  const joinOk = typeof p.join === "string" && p.join.startsWith(playerName) && p.join.includes("加入了生存界");
  return mainOk && nameOk && joinOk;
}
// 内容合法性粗校验（食材/食谱 JSON 结构；音效为 base64 字符串，不做 JSON 解析）
function contentLooksValid(type, content) {
  if (type === "sound") {
    return typeof content === "string" && content.length > 0;
  }
  try {
    const o = typeof content === "string" ? JSON.parse(content) : content;
    if (type === "food") {
      if (!o || typeof o.name !== "string") return false;
      if (o.elements) {
        for (const v of Object.values(o.elements)) {
          const n = Number(v);
          if (!Number.isFinite(n) || n < -6 || n > 6) return false;
        }
      }
      return true;
    }
    if (type === "recipe") {
      return !!o && Array.isArray(o.ingredients) && o.ingredients.length > 0;
    }
    if (type === "half") {
      return !!o && typeof o.name === "string";
    }
    // 食材元素库：与食材投稿同构（{"name","elements","data":[条目]}），
    // 额外要求 data 为条目数组且每条有名称；元素值 -6..6、效果等级 1..9。
    if (type === "element") {
      if (!o || typeof o.name !== "string") return false;
      if (o.elements) {
        for (const v of Object.values(o.elements)) {
          const n = Number(v);
          if (!Number.isFinite(n) || n < -6 || n > 6) return false;
        }
      }
      if (!Array.isArray(o.data) || o.data.length === 0 || o.data.length > 200) return false;
      for (const it of o.data) {
        if (!it || typeof it.name !== "string" || !it.name.trim()) return false;
        if (it.elements) {
          for (const v of Object.values(it.elements)) {
            const n = Number(v);
            if (!Number.isFinite(n) || n < -6 || n > 6) return false;
          }
        }
        if (it.effects) {
          for (const v of Object.values(it.effects)) {
            const n = Number(v);
            if (!Number.isFinite(n) || n < 1 || n > 9) return false;
          }
        }
      }
      return true;
    }
    return false;
  } catch { return false; }
}

// 食材元素库授权上传者名单（公共仓 notices/uploaders.json）
// v:2 起支持 uuids（更可靠）；names 保留用于后台展示与老数据兼容
async function uploaderAuth(token) {
  const f = await ghRead(PUBLIC_REPO, "notices/uploaders.json", token);
  if (!f) return { names: [], uuids: [] };
  try {
    const o = JSON.parse(f.content);
    return {
      names: Array.isArray(o.names) ? o.names.map(String) : [],
      uuids: Array.isArray(o.uuids) ? o.uuids.map((x) => String(x).toLowerCase()) : [],
    };
  } catch { return { names: [], uuids: [] }; }
}
async function uploaderList(token) {
  return (await uploaderAuth(token)).names;
}
// 授权判定：uuid 命中直接放行；否则按名（大小写不敏感）。名字用于后台友好展示，uuid 才是硬身份
function isAuthorizedUploader(auth, name, uuid) {
  if (uuid && auth.uuids.includes(String(uuid).toLowerCase())) return true;
  if (!name) return false;
  const n = String(name).toLowerCase();
  return auth.names.some((x) => String(x).toLowerCase() === n);
}
async function uploaderWrite(token, names, uuids) {
  const existing = await ghRead(PUBLIC_REPO, "notices/uploaders.json", token);
  const body = { message: "食材元素库授权名单更新", content: toB64(JSON.stringify({ v: 2, names, uuids: uuids || [] })) };
  if (existing) body.sha = existing.sha;
  return ghJson(`/repos/${PUBLIC_REPO}/contents/notices/uploaders.json`, token, {
    method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
  });
}

// 凭据 -> 真实身份：accountKey 索引里的 uuid，再读该 uuid 的账号记录取注册时绑定的玩家名。
// 投稿与元素库上传都用这个「绑定名」判定，避免请求里自报 senderName 冒充他人。
async function identityOf(accountKey, token) {
  if (!/^[a-z0-9]{32}$/.test(String(accountKey || ""))) return null;
  const idx = await ghRead(MEMBER_REPO, `accounts/${accountKey}.json`, token);
  if (!idx) return null;
  let rec;
  try { rec = JSON.parse(idx.content); } catch { return null; }
  const uuid = String(rec.uuid || "").toLowerCase();
  if (!validUuid(uuid)) return null;
  let playerName = String(rec.playerName || "");
  const acc = await ghRead(MEMBER_REPO, `users/${uuid}/account.json`, token);
  if (acc) {
    try {
      const a = JSON.parse(acc.content);
      if (a.playerName) playerName = String(a.playerName);
    } catch (_) {}
  }
  return { uuid, playerName };
}

