// 读分区索引（返回条目数组，无则 []）
async function pubIndex(type, token) {
  const dir = PUB_DIRS[type];
  if (!dir) return [];
  const idx = await ghRead(PUBLIC_REPO, `public/${dir}/index.json`, token);
  if (!idx) return [];
  try { return JSON.parse(idx.content); } catch { return []; }
}
async function pubIndexWrite(type, token, arr, msg) {
  const dir = PUB_DIRS[type];
  const existing = await ghRead(PUBLIC_REPO, `public/${dir}/index.json`, token);
  const body = { message: msg, content: toB64(JSON.stringify(arr)) };
  if (existing) body.sha = existing.sha;
  const r = await ghJson(`/repos/${PUBLIC_REPO}/contents/public/${dir}/index.json`, token, {
    method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
  });
  // 关键：写入成功后必须使 ghRead 的 20s 缓存失效，否则连续写索引会用旧 sha 导致 409
  if (r.ok) ghInvalidate(PUBLIC_REPO, `public/${dir}/index.json`);
  return r;
}
// 点赞排序分值：赞数权重 + 新近度加权（推荐排序用）
function recScore(it) {
  const likes = Number(it.likes || 0);
  const ageH = Math.max(0.1, (Date.now() - new Date(it.acceptedAt || Date.now()).getTime()) / 3600_000);
  return likes * 10 + 3 / (1 + ageH / 24);
}

async function handler(req, env, ctx) {
  ENV = env;
  const url = new URL(req.url);
  const ip = req.headers.get("cf-connecting-ip") || req.headers.get("x-forwarded-for")?.split(",")[0] || "unknown";
  if (!rateLimit(ip)) return json({ ok: false, error: "请求过于频繁，请稍后再试" }, 429);

  const memberToken = env.MEMBER_TOKEN;
  const publicToken = env.PUBLIC_TOKEN;
  if (!memberToken || !publicToken) return json({ ok: false, error: "端点未配置完成" }, 500);
  // 惰性播种：元素库首次初始化（幂等，index 存在即跳过），后台执行不阻塞响应
  try { seedElements(publicToken).catch((e) => console.error("LAZY SEED ERR " + String(e))); } catch (e) { /* 忽略 */ }

  try {
    // ---------- 健康检查 ----------
    if (url.pathname === "/" || url.pathname === "/api/health") {
      return json({ ok: true, service: "dc-food-lib", time: Date.now() });
    }

    // ---------- 食域账号注册 ----------
    if (url.pathname === "/api/v1/account/register" && req.method === "POST") {
      const b = await req.json();
      const { uuid, playerName, loginProof } = b;
      if (!validUuid(uuid)) return bad("UUID 格式无效");
      if (!validName(playerName)) return bad("玩家名无效");
      if (!verifyLoginProof(loginProof, playerName)) return bad("登录信号校验未通过");

      const uuidL = uuid.toLowerCase();
      const nameKey = playerName.toLowerCase();
      // 玩家名绑定：一个名字只能属于一个 uuid。这是防冒名的根：别人抢注不到你的名字，
      // 后续投稿/元素库上传按账号绑定名判定，落款写谁都没用。
      const bind = await ghRead(MEMBER_REPO, `names/${nameKey}.json`, memberToken);
      if (bind) {
        let bound = "";
        try { bound = String(JSON.parse(bind.content).uuid || "").toLowerCase(); } catch (_) {}
        if (bound && bound !== uuidL) {
          return json({
            ok: false,
            error: "该玩家名已被其他账号绑定；如果你确为本人，请联系作者在后台解绑后重新登录",
            code: "nameTaken",
          }, 409);
        }
      }

      const base = `users/${uuidL}`;
      const existing = await ghRead(MEMBER_REPO, `${base}/account.json`, memberToken);
      const accountKey = genKey();
      const bindOk = async () => {
        const wb = await ghWrite(MEMBER_REPO, `names/${nameKey}.json`, memberToken,
          JSON.stringify({ v: 1, uuid: uuidL, playerName, boundAt: new Date().toISOString() }), "玩家名绑定");
        return wb.ok || !!bind;   // 已有绑定记录时写入失败不致命
      };
      if (existing) {
        // 已有账号：重新领取凭据（本人凭登录信号+UUID 可重置）
        const acc = { ...JSON.parse(existing.content), playerName, accountKeyHash: await sha256hex(accountKey), refreshedAt: new Date().toISOString() };
        const w1 = await ghWrite(MEMBER_REPO, `${base}/account.json`, memberToken, JSON.stringify(acc), "食域账号凭据刷新");
        const w2 = await ghWrite(MEMBER_REPO, `accounts/${accountKey}.json`, memberToken, JSON.stringify({ uuid: uuidL, playerName }), "食域账号索引");
        if (!w1.ok || !w2.ok) return json({ ok: false, error: "账号更新失败" }, 502);
        await bindOk();
        return json({ ok: true, accountKey, existed: true, refreshed: true, playerName, uuid: uuidL });
      }
      const acc = {
        uuid: uuidL,
        playerName,
        accountKeyHash: await sha256hex(accountKey),
        createdAt: new Date().toISOString(),
      };
      const w1 = await ghWrite(MEMBER_REPO, `${base}/account.json`, memberToken, JSON.stringify(acc), "食域账号注册");
      const w2 = await ghWrite(MEMBER_REPO, `accounts/${accountKey}.json`, memberToken, JSON.stringify({ uuid: uuidL, playerName }), "食域账号索引");
      if (!w1.ok || !w2.ok) return json({ ok: false, error: "账号写入失败" }, 502);
      await bindOk();
      return json({ ok: true, accountKey, existed: false, playerName, uuid: uuidL });
    }

    // ---------- 私有数据读取 ----------
    if (url.pathname === "/api/v1/private/get" && req.method === "GET") {
      const accountKey = url.searchParams.get("accountKey") || "";
      const kind = url.searchParams.get("kind") || "";
      const path = url.searchParams.get("path") || "";
      if (!/^[a-z0-9]{32}$/.test(accountKey)) return bad("凭据无效");
      if (!["fooddata", "recipes", "sounds"].includes(kind)) return bad("kind 无效");
      if (!/^[A-Za-z0-9_\-\.]{1,64}$/.test(path)) return bad("path 无效");

      // 通过 accountKey 找所属 uuid：accountKey 关联存于 index：accounts/{key}.json
      const idx = await ghRead(MEMBER_REPO, `accounts/${accountKey}.json`, memberToken);
      if (!idx) return bad("账号不存在或凭据错误", 404);
      const rec = JSON.parse(idx.content);
      const full = kind === "sounds" ? `users/${rec.uuid}/sounds/${path}` : `users/${rec.uuid}/${kind}/${path}`;
      const data = await ghRead(MEMBER_REPO, full, memberToken);
      if (!data) return json({ ok: true, data: null });
      return json({ ok: true, data: data.content });
    }

    // ---------- 私有数据写入 ----------
    if (url.pathname === "/api/v1/private/put" && req.method === "POST") {
      const b = await req.json();
      const { accountKey, kind, path, data } = b;
      if (!/^[a-z0-9]{32}$/.test(accountKey || "")) return bad("凭据无效");
      if (!["fooddata", "recipes", "sounds"].includes(kind)) return bad("kind 无效");
      if (!/^[A-Za-z0-9_\-\.]{1,64}$/.test(path || "")) return bad("path 无效");
      if (typeof data !== "string" || data.length === 0 || data.length > MAX_BODY) return bad("数据为空或过大");

      const idx = await ghRead(MEMBER_REPO, `accounts/${accountKey}.json`, memberToken);
      if (!idx) return bad("账号不存在或凭据错误", 404);
      const rec = JSON.parse(idx.content);
      const full = kind === "sounds" ? `users/${rec.uuid}/sounds/${path}` : `users/${rec.uuid}/${kind}/${path}`;
      const wr = await ghWrite(MEMBER_REPO, full, memberToken, data, "食域私有数据更新");
      if (!wr.ok) return json({ ok: false, error: "写入失败" }, 502);
      return json({ ok: true });
    }

    // ---------- 公有投稿（自动审核）----------
    // 稿件通过结构校验后立即入库公共库并记入采纳清单（含投稿者落款），玩家可即时在【检查采纳】看到反馈；
    // 无需人工等待。投稿频率受限（同一出口每 60s 最多 2 次，防刷）。
    // 食材元素库（element）额外维护"每投稿名一条"：同名旧条目先清理再入库（库内始终是最新数据）。
    async function publishEntry(type, name, content, senderName, rateKey) {
      if (!PUB_TYPES.includes(type)) return { error: "type 无效", status: 400 };
      if (!validName(name || "")) return { error: "名称无效", status: 400 };
      if (!contentLooksValid(type, content)) return { error: "内容格式校验未通过", status: 400 };
      const smin = Math.floor(Date.now() / 60000);
      const se = rateMap.get(rateKey);
      if (se && se.t === smin && se.n >= 2) return { error: "投稿过于频繁，请一分钟后再试", status: 429 };
      if (!se || se.t !== smin) rateMap.set(rateKey, { t: smin, n: 1 });
      else se.n += 1;
      // 食材元素库：先清掉同名旧条目（文件+索引+采纳落款），保持"每食材组一条、以最新为准"
      if (type === "element") {
        try {
          const oldIdx = await pubIndex(type, publicToken);
          for (const o of oldIdx) {
            if (String(o.name || "") === name) {
              await deletePubEntry(type, String(o.ticket || ""), true);
            }
          }
        } catch (_) {}
      }
      const ticket = genKey();
      const item = {
        v: 1,
        ticket,
        type,
        name,
        content,
        senderName: validName(senderName || "") ? senderName : null,
        acceptedAt: new Date().toISOString(),
      };
      const safeName = String(name).replace(/[^\w\u4e00-\u9fa5-]+/g, "_");
      const pubPath = `public/${PUB_DIRS[type]}/${safeName}-${ticket.slice(0, 8)}.json`;
      const wr = await ghWrite(PUBLIC_REPO, pubPath, publicToken, JSON.stringify(item), `采纳 ${type}: ${name}`);
      if (!wr.ok) return { error: "自动审核入库失败", status: 502 };
      // 分区索引同步（公共浏览用）
      const idxArr = await pubIndex(type, publicToken);
      idxArr.unshift({ v: 1, ticket, type, name, senderName: item.senderName || "匿名", acceptedAt: item.acceptedAt, likes: 0 });
      if (idxArr.length > 1000) idxArr.length = 1000;
      const wi = await pubIndexWrite(type, publicToken, idxArr, `索引 ${type}: ${name}`);
      if (!wi.ok) return { error: "公共索引更新失败", status: 502 };
      const notice = { v: 1, ticket, type, name, senderName: item.senderName || "匿名", acceptedAt: item.acceptedAt };
      const existing = await ghRead(PUBLIC_REPO, "notices/accepted.json", publicToken);
      const list = existing ? JSON.parse(existing.content) : [];
      list.unshift(notice);
      if (list.length > 200) list.length = 200;
      const w2 = await ghWrite(PUBLIC_REPO, "notices/accepted.json", publicToken, JSON.stringify(list), `采纳落款 ${type}: ${name}`);
      if (!w2.ok) return { error: "采纳清单写入失败", status: 502 };
      // 元素库：同步维护 all.json 聚合快照（elements/all 接口只读这个文件，不维护就会一直停在种子数据）
      if (type === "element") {
        try {
          const allRec = await ghRead(PUBLIC_REPO, "public/elements/all.json", publicToken);
          let allArr = allRec ? JSON.parse(allRec.content) : [];
          if (!Array.isArray(allArr)) allArr = [];
          // 去掉同名旧条目（新条目已 unshift，同名旧记录在 L630 已删单文件但 all.json 里仍残留）
          allArr = allArr.filter((x) => String(x.name || "") !== name);
          allArr.push(item);
          await ghWrite(PUBLIC_REPO, "public/elements/all.json", publicToken, JSON.stringify(allArr), `聚合元素库: ${name}`);
          try { await kvDelPrefix(["elements-all"]); } catch (_) {}
        } catch (e) { console.error("ALLJSON 聚合失败", String(e)); }
      }
      return { ok: true, ticket };
    }
    // ---------- 公有投稿 ----------
    // 策略：食材 / 食谱 / 半成品 / 音效 —— 结构校验通过即入库（不需要审核）；
    //      食材元素库（element）—— 只有授权名单内玩家可直接入库，其他玩家进 pending 待审核。
    // 身份：一律以账号凭据解析出的绑定名 + uuid 为准；请求里自报的 senderName 只作为「自称」记录，
    //      绝不用于授权判定或落款（否则谁都能把落款写成白名单玩家冒名入库）。
    if (url.pathname === "/api/v1/public/submit" && req.method === "POST") {
      const b = await req.json();
      const type = String(b.type || "");
      if (!PUB_TYPES.includes(type)) return json({ ok: false, error: "type 无效" }, 400);
      if (!validName(b.name || "")) return json({ ok: false, error: "名称无效" }, 400);
      if (!contentLooksValid(type, b.content)) return json({ ok: false, error: "内容格式校验未通过" }, 400);
      const id = await identityOf(b.accountKey, memberToken);
      const bound = id && validName(id.playerName) ? id.playerName : "";
      const claimed = validName(b.senderName || "") ? String(b.senderName) : "";
      // 非元素库：结构合法即入库；落款用绑定名，没有凭据记「匿名」
      if (type !== "element") {
        const author = bound || "匿名";
        const r = await publishEntry(type, b.name, b.content, author, "submit:" + ip);
        if (!r.ok) return json({ ok: false, error: r.error }, r.status);
        return json({ ok: true, ticket: r.ticket, accepted: true, author });
      }
      // 元素库：必须携带有效账号凭据；落款与授权判定都只认凭据绑定的玩家名 + uuid
      if (!bound) return json({ ok: false, error: "元素库投稿必须携带食域账号凭据：请先进入服务器完成 DC 登录后再试" }, 401);
      const auth = await uploaderAuth(publicToken);
      if (isAuthorizedUploader(auth, bound, id.uuid)) {
        const r = await publishEntry(type, b.name, b.content, bound, "submit:" + ip);
        if (!r.ok) return json({ ok: false, error: r.error }, r.status);
        return json({ ok: true, ticket: r.ticket, accepted: true, author: bound });
      }
      // 凭据有效但不在名单内：进待审，等管理员后台点"通过"才公开
      const ticket = genKey();
      const item = {
        v: 1, ticket, type,
        name: b.name, content: b.content,
        senderName: bound,
        claimedName: claimed || null,
        acceptedAt: new Date().toISOString(),
      };
      const wp = await ghWrite(PUBLIC_REPO, `pending/${ticket}.json`, publicToken, JSON.stringify(item), `待审投稿 ${type}: ${b.name} by ${item.senderName}`);
      if (!wp.ok) return json({ ok: false, error: "投稿失败，请稍后再试" }, 502);
      return json({ ok: true, ticket, accepted: false, pending: true, author: bound });
    }
    // ---------- 食材元素库 · 授权上传（管理端授权玩家专属）----------
    // 只有 notices/uploaders.json 名单内的玩家可直接更新元素库；未授权玩家请先由作者在后台授权。
    // 授权名单公开路由：客户端直接走服务端实时读取（GitHub API 无 CDN 缓存），
    // 避免直连 raw/jsDelivr 缓存延迟导致"刚授权仍提示无权限"。
    if (url.pathname === "/api/v1/public/uploaders" && req.method === "GET") {
      return json({ ok: true, names: await uploaderList(publicToken) }, 200, { "Cache-Control": "public, max-age=300" });
    }
    // 食域元素库全量：由 Worker 代理 GitHub all.json（ghRead 带内存缓存 + 边缘缓存头），
    // 客户端不再直连 raw/jsDelivr（国内网络常不可达），彻底解决"元素库拉取失败"。
    // 2.7.7：加真实 KV 持久缓存（600s），冷启动/跨 isolate 不再回源 GitHub，保证秒回。
    if (url.pathname === "/api/v1/public/elements/all" && req.method === "GET") {
      let data = null;
      try { data = await kvGetBig(["elements-all"]); } catch (_) {}
      if (data == null) {
        const rec = await ghRead(PUBLIC_REPO, "public/elements/all.json", publicToken);
        if (!rec) return json({ ok: false, error: "元素库暂不可用" }, 502);
        try { data = JSON.parse(rec.content); } catch (_) { data = []; }
        if (Array.isArray(data) && data.length > 0) {
          try { await kvSetBig(["elements-all"], data, 600_000); } catch (_) {}
        }
      }
      return json({ ok: true, data }, 200, { "Cache-Control": "public, max-age=600" });
    }
    if (url.pathname === "/api/v1/public/element-upload" && req.method === "POST") {
      const b = await req.json();
      if (!validName(b.name || "")) return json({ ok: false, error: "名称无效" }, 400);
      if (!contentLooksValid("element", b.content)) return json({ ok: false, error: "内容格式校验未通过" }, 400);
      const id = await identityOf(b.accountKey, memberToken);
      const bound = id && validName(id.playerName) ? id.playerName : "";
      const claimed = validName(b.senderName || "") ? String(b.senderName) : "";
      // 元素库落款只认凭据绑定名：无有效凭据直接拒绝，不再回退到请求里的署名
      if (!bound) return json({ ok: false, error: "元素库上传必须携带食域账号凭据：请先进入服务器完成 DC 登录后再试" }, 401);
      const auth = await uploaderAuth(publicToken);
      // 授权名单内（uuid 命中或绑定名命中）：结构合法即入库，同名旧条目以新数据为准
      if (isAuthorizedUploader(auth, bound, id.uuid)) {
        const r = await publishEntry("element", b.name, b.content, bound, "elementup:" + ip);
        if (!r.ok) return json({ ok: false, error: r.error }, r.status);
        return json({ ok: true, ticket: r.ticket, accepted: true, author: bound });
      }
      // 凭据有效但不在名单内：先进待审队列，作者在后台点通过后才会写进元素库
      const ticket = genKey();
      const item = {
        v: 1, ticket, type: "element",
        name: b.name, content: b.content,
        senderName: bound,
        claimedName: claimed || null,
        acceptedAt: new Date().toISOString(),
      };
      const wp = await ghWrite(PUBLIC_REPO, `pending/${ticket}.json`, publicToken, JSON.stringify(item), `待审元素库 ${b.name} by ${item.senderName}`);
      if (!wp.ok) return json({ ok: false, error: "上传失败，请稍后再试" }, 502);
      return json({ ok: true, ticket, accepted: false, pending: true, author: bound });
    }

    // ---------- 审核采纳（管理端，memberToken 鉴权）----------
    // 用途：投稿经人工审核通过后，由模组作者（或授权者）一键采纳：
    //   读 pending/{ticket}.json → 内容写入公共库 public/{type}s/{name}-{ticket8}.json
    //   → 采纳清单（含投稿者落款）写入 notices/accepted.json → 删除 pending。
    if (url.pathname === "/api/v1/public/accept" && req.method === "POST") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无审核权限" }, 403);
      const b = await req.json();
      const ticket = (b && b.ticket) || "";
      if (!/^[a-z0-9]{32}$/.test(ticket)) return bad("ticket 无效");
      const pend = await ghRead(PUBLIC_REPO, `pending/${ticket}.json`, publicToken);
      if (!pend) return json({ ok: false, error: "投稿不存在或已处理" }, 404);
      const item = JSON.parse(pend.content);
      const safeName = String(item.name || "unnamed").replace(/[^\w\u4e00-\u9fa5-]+/g, "_");
      const pubPath = `public/${item.type}s/${safeName}-${ticket.slice(0, 8)}.json`;
      const wr = await ghWrite(PUBLIC_REPO, pubPath, publicToken, JSON.stringify(item), `采纳 ${item.type}: ${item.name}`);
      if (!wr.ok) return json({ ok: false, error: "公共库写入失败" }, 502);
      const notice = {
        v: 1,
        ticket,
        type: item.type,
        name: item.name,
        senderName: item.senderName || "匿名",
        acceptedAt: new Date().toISOString(),
      };
      const existing = await ghRead(PUBLIC_REPO, "notices/accepted.json", publicToken);
      const list = existing ? JSON.parse(existing.content) : [];
      list.unshift(notice);
      const w2 = await ghWrite(PUBLIC_REPO, "notices/accepted.json", publicToken, JSON.stringify(list), `采纳落款 ${item.type}: ${item.name}`);
      if (!w2.ok) return json({ ok: false, error: "采纳清单写入失败" }, 502);
      // 公共库分区索引同步（浏览/搜索/点赞用）——此前缺失导致文件在、浏览空
      const accIdx = await pubIndex(item.type, publicToken);
      accIdx.unshift({ v: 1, ticket, type: item.type, name: item.name, senderName: item.senderName || "匿名", acceptedAt: notice.acceptedAt, likes: 0 });
      if (accIdx.length > 1000) accIdx.length = 1000;
      const wIdx = await pubIndexWrite(item.type, publicToken, accIdx, `采纳索引 ${item.type}: ${item.name}`);
      if (!wIdx.ok) return json({ ok: false, error: "公共库索引更新失败" }, 502);
      // 元素库：采纳后同步 upsert all.json 聚合快照
      if (item.type === "element") {
        try {
          const allRec = await ghRead(PUBLIC_REPO, "public/elements/all.json", publicToken);
          let allArr = allRec ? JSON.parse(allRec.content) : [];
          if (!Array.isArray(allArr)) allArr = [];
          allArr = allArr.filter((x) => String(x.name || "") !== item.name && x.ticket !== ticket);
          allArr.push(item);
          await ghWrite(PUBLIC_REPO, "public/elements/all.json", publicToken, JSON.stringify(allArr), `采纳聚合元素库: ${item.name}`);
          try { await kvDelPrefix(["elements-all"]); } catch (_) {}
        } catch (e) { console.error("ACCEPT ALLJSON ERR", String(e)); }
      }
      const del = await ghJson(`/repos/${PUBLIC_REPO}/contents/pending/${ticket}.json`, publicToken, {
        method: "DELETE", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: `采纳清理 ${item.name}`, sha: pend.sha }),
      });
      return json({ ok: true, notice, pendingCleared: !!del.ok });
    }

    // ---------- 管理端：删除待审投稿 ----------
    if (url.pathname === "/api/v1/admin/pending-delete" && req.method === "POST") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      const b = await req.json();
      const ticket = (b && b.ticket) || "";
      if (!/^[a-z0-9]{32}$/.test(ticket)) return bad("ticket 无效");
      const pend = await ghRead(PUBLIC_REPO, `pending/${ticket}.json`, publicToken);
      if (!pend) return json({ ok: false, error: "投稿不存在或已处理" }, 404);
      const del = await ghJson(`/repos/${PUBLIC_REPO}/contents/pending/${ticket}.json`, publicToken, {
        method: "DELETE", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: `删除待审 ${ticket}`, sha: pend.sha }),
      });
      return json({ ok: true, pendingCleared: !!del.ok });
    }

    // ---------- 食域中转分享（提取码，离线可收）----------
    // 分享方把数据写入私有仓库 inbox/{ticket}.json 换取 32 位提取码；
    // 接收方凭码读取，72 小时内有效。全程不依赖对方在线，不经过公共仓库。
    if (url.pathname === "/api/v1/transfer/put" && req.method === "POST") {
      const b = await req.json();
      const type = String(b.type || "").replace(/[^a-z0-9]/g, "");
      const payload = b.payload;
      if (!type || !payload || typeof payload !== "object") return bad("参数无效");
      const senderName = String(b.senderName || "匿名").slice(0, 32);
      const name = String(b.name || "数据").slice(0, 64);
      const receivers = Array.isArray(b.receivers) ? b.receivers.map((x) => String(x).slice(0, 32)) : [];
      const ticket = crypto.randomUUID().replace(/-/g, "");
      const createdAt = new Date().toISOString();
      const deleteAt = Date.now() + 24 * 3600_000; // 兜底 24h；玩家收到提示时刷新为 now+5min
      const rec = { v: 1, ticket, type, name, senderName, createdAt, receivers, deleteAt, payload };
      const wr = await ghWrite(MEMBER_REPO, `inbox/${ticket}.json`, memberToken, JSON.stringify(rec), `分享中转 ${type}: ${name}`);
      if (!wr.ok) return json({ ok: false, error: "中转写入失败" }, 502);
      // 维护收件箱索引（元数据不携带 payload，供收件人查询）
      const idxF = await ghRead(MEMBER_REPO, "inbox-index.json", memberToken);
      const idx = idxF ? JSON.parse(idxF.content) : { v: 1, items: [] };
      idx.items = idx.items || [];
      idx.items.unshift({ ticket, type, name, senderName, receivers, createdAt, deleteAt });
      if (idx.items.length > 5000) idx.items.length = 5000;
      await ghWrite(MEMBER_REPO, "inbox-index.json", memberToken, JSON.stringify(idx), "收件箱索引 +1");
      return json({ ok: true, ticket, expiresIn: 600, pending: receivers.length > 0 });
    }
    if (url.pathname === "/api/v1/transfer/get" && req.method === "GET") {
      const ticket = (url.searchParams.get("ticket") || "").toLowerCase();
      if (!/^[a-z0-9]{32}$/.test(ticket)) return bad("提取码无效");
      const rec = await ghRead(MEMBER_REPO, `inbox/${ticket}.json`, memberToken);
      if (!rec) return json({ ok: false, error: "分享不存在或已失效" }, 404);
      const item = JSON.parse(rec.content);
      if (Number(item.deleteAt || 0) < Date.now()) {
        await ghDelete(MEMBER_REPO, `inbox/${ticket}.json`, memberToken, "分享已过期清理");
        return json({ ok: false, error: "分享已过期（5 分钟内有效）" }, 410);
      }
      return json({ ok: true, type: item.type, name: item.name, senderName: item.senderName, payload: item.payload, ttl: Math.max(0, Math.floor((Number(item.deleteAt || 0) - Date.now()) / 1000)) });
    }
    if (url.pathname === "/api/v1/transfer/inbox" && req.method === "GET") {
      // 玩家上线后拉取「发给我的云端分享」：命中即视为已提示，并把该批分享的失效时间刷新为 now+5min
      const who = (url.searchParams.get("name") || "").slice(0, 32);
      if (!who) return bad("参数无效");
      const idxF = await ghRead(MEMBER_REPO, "inbox-index.json", memberToken);
      if (!idxF) return json({ ok: true, items: [] });
      let idx = JSON.parse(idxF.content);
      const items = idx.items || [];
      const now = Date.now();
      const mine = items.filter((it) => Array.isArray(it.receivers) && it.receivers.some((r) => String(r).toLowerCase() === who.toLowerCase()) && Number(it.deleteAt || 0) > now);
      if (mine.length > 0) {
        const fresh = new Set(mine.map((it) => it.ticket));
        let changed = false;
        for (const it of items) {
          if (fresh.has(it.ticket)) { it.deleteAt = now + 5 * 60_000; changed = true; }
        }
        if (changed) {
          idx = { v: 1, items };
          await ghWrite(MEMBER_REPO, "inbox-index.json", memberToken, JSON.stringify(idx), "收件箱提示刷新");
        }
      }
      const out = mine.map((it) => ({ ticket: it.ticket, type: it.type, name: it.name, senderName: it.senderName, ttl: Math.max(0, Math.floor((Number(it.deleteAt || 0) - now) / 1000)) }));
      return json({ ok: true, items: out });
    }

    // ---------- 采纳清单（反馈轮询）----------
    if (url.pathname === "/api/v1/public/notices" && req.method === "GET") {
      const data = await ghRead(PUBLIC_REPO, "notices/accepted.json", publicToken);
      if (!data) return json({ ok: true, notices: [] });
      return json({ ok: true, notices: JSON.parse(data.content) });
    }

    // ---------- 公共库浏览（列表/搜索/排序/点赞/查看/管理）----------
    if (url.pathname === "/api/v1/public/list" && req.method === "GET") {
      const type = url.searchParams.get("type") || "food";
      if (!PUB_TYPES.includes(type)) return bad("type 无效");
      const sort = url.searchParams.get("sort") || "rec";
      const q = (url.searchParams.get("q") || "").trim().toLowerCase();
      let arr = await pubIndex(type, publicToken);
      if (q) arr = arr.filter((it) => (String(it.name || "").toLowerCase().includes(q) || String(it.senderName || "").toLowerCase().includes(q)));
      if (sort === "hot") arr = arr.slice().sort((a, b) => (Number(b.likes || 0) - Number(a.likes || 0)) || (String(b.acceptedAt) < String(a.acceptedAt) ? -1 : 1));
      else if (sort === "time") arr = arr.slice().sort((a, b) => String(b.acceptedAt) < String(a.acceptedAt) ? -1 : 1);
      else arr = arr.slice().sort((a, b) => recScore(b) - recScore(a));
      return json({ ok: true, type, items: arr.slice(0, 300) });
    }
    if (url.pathname === "/api/v1/public/like" && req.method === "POST") {
      const b = await req.json();
      const type = String(b.type || "");
      const ticket = String(b.ticket || "").toLowerCase();
      if (!PUB_TYPES.includes(type) || !/^[a-z0-9]{32}$/.test(ticket)) return bad("参数无效");
      const lk = "like:" + ip;
      const lmin = Math.floor(Date.now() / 60000);
      const le = rateMap.get(lk);
      if (le && le.t === lmin && le.n >= 10) return json({ ok: false, error: "点赞过于频繁" }, 429);
      if (!le || le.t !== lmin) rateMap.set(lk, { t: lmin, n: 1 }); else le.n += 1;
      const dir = PUB_DIRS[type];
      // 冲突重试：每轮强制回源读最新索引 → +1 → 写入；版本冲突(409)时重试，防止并发点赞/旧缓存覆盖导致赞数回退
      let lastErr = "点赞写入失败";
      for (let i = 0; i < 4; i++) {
        ghInvalidate(PUBLIC_REPO, `public/${dir}/index.json`);
        const arr = await pubIndex(type, publicToken);
        const it = arr.find((x) => x.ticket === ticket);
        if (!it) return json({ ok: false, error: "条目不存在" }, 404);
        it.likes = Number(it.likes || 0) + 1;
        const w = await pubIndexWrite(type, publicToken, arr, `点赞 ${ticket}`);
        if (w.ok) return json({ ok: true, likes: it.likes });
        if (w.status !== 409) break;
        lastErr = "点赞冲突，正在重试";
      }
      return json({ ok: false, error: lastErr }, 502);
    }
    if (url.pathname === "/api/v1/public/get" && req.method === "GET") {
      const type = url.searchParams.get("type") || "";
      const ticket = (url.searchParams.get("ticket") || "").toLowerCase();
      const meta = url.searchParams.get("meta") === "1";
      if (!PUB_TYPES.includes(type) || !/^[a-z0-9]{32}$/.test(ticket)) return bad("参数无效");
      const dir = PUB_DIRS[type];
      if (type === "sound") {
        const t0 = Date.now();
        try {
          const kobj = await kvGetBig(["sndpub", ticket]);
          if (kobj) {
            if (typeof kobj.name === "string" && kobj.name) {
              kobj.dlUrl = "https://cdn.jsdelivr.net/gh/" + PUBLIC_REPO + "@main/public/sounds/" + encodeURIComponent(kobj.name + "-" + ticket.slice(0, 8) + ".json");
            }
            if (meta) kobj.content = "";
            try {
              const _idx = await pubIndex(type, publicToken);
              const _m = _idx.find((x) => x.ticket === ticket);
              if (_m) kobj.likes = Number(_m.likes || 0);
            } catch (_) {}
            console.error("SND KV HIT ms=" + (Date.now() - t0)); return json({ ok: true, item: kobj });
          }
          console.error("SND KV MISS ms=" + (Date.now() - t0));
        } catch (e) { console.error("SND KV ERR", String(e)); }
      }
      const lst = await ghJson(`/repos/${PUBLIC_REPO}/contents/public/${dir}`, publicToken);
      if (!lst.ok || !Array.isArray(lst.data)) return json({ ok: false, error: "读取失败" }, 502);
      const f = lst.data.find((x) => x.name.endsWith("-" + ticket.slice(0, 8) + ".json"));
      let seedHit = null;
      if (!f && type === "element") {
        // 种子条目以捆绑文件 all.json 存储（152 条单文件写入，规避 50 子请求限制）
        const allRec = await ghRead(PUBLIC_REPO, `public/${dir}/all.json`, publicToken);
        if (allRec) {
          try { const _all = JSON.parse(allRec.content); seedHit = _all.find((x) => x.ticket === ticket) || null; } catch (_) {}
        }
      }
      if (!f && !seedHit) return json({ ok: false, error: "条目不存在" }, 404);
      let item = null;
      if (type === "sound") {
        const t1 = Date.now();
        const raw = await jdRead(`public/${dir}/${f.name}`);
        if (raw) { try { item = JSON.parse(raw); } catch (_) { item = null; } }
        console.error("SND JSDELIVR " + (item ? "OK" : "FAIL") + " ms=" + (Date.now() - t1));
      }
      if (!item && seedHit) item = seedHit;
      if (!item && f) {
        const rec = await ghRead(PUBLIC_REPO, `public/${dir}/${f.name}`, publicToken);
        if (!rec) return json({ ok: false, error: "条目不存在" }, 404);
        item = JSON.parse(rec.content);
      }
      if (!item) return json({ ok: false, error: "条目不存在" }, 404);
      if (type === "sound") {
        if (meta && item) item.content = "";
        if (item && typeof item.name === "string" && item.name) {
          item.dlUrl = "https://cdn.jsdelivr.net/gh/" + PUBLIC_REPO + "@main/public/sounds/" + encodeURIComponent(item.name + "-" + ticket.slice(0, 8) + ".json");
        }
        try { await kvSetBig(["sndpub", ticket], item, 7 * 86400_000); } catch (e) { console.error("SND KV SET ERR", String(e)); }
      }
      if (item) {
        try {
          const _idx = await pubIndex(type, publicToken);
          const _m = _idx.find((x) => x.ticket === ticket);
          if (_m) item.likes = Number(_m.likes || 0);
        } catch (_) {}
      }
      return json({ ok: true, item });
    }
    // ---------- 公共库删除辅助（文件+索引+音效缓存清理）----------
    // admin=true 时跳过条目内容凭据校验（管理端强制删除，可清理数据异常的顽固条目）
    async function deletePubEntry(type, ticket, admin) {
      const dir = PUB_DIRS[type];
      const lst = await ghJson(`/repos/${PUBLIC_REPO}/contents/public/${dir}`, publicToken);
      if (!lst.ok || !Array.isArray(lst.data)) return { ok: false, error: "读取失败" };
      const f = lst.data.find((x) => x.name.endsWith("-" + ticket.slice(0, 8) + ".json") && x.name !== "index.json");
      if (!f) {
        // 文件已不存在（孤儿索引记录）：仍从索引移除，保证后台列表不再显示
        const arr = (await pubIndex(type, publicToken)).filter((x) => x.ticket !== ticket);
        const w = await pubIndexWrite(type, publicToken, arr, `索引清理孤儿 ${ticket}`);
        if (!w.ok) return { ok: false, error: "索引更新失败" };
        return { ok: true, name: ticket.slice(0, 8), orphan: true };
      }
      const rec = await ghRead(PUBLIC_REPO, `public/${dir}/${f.name}`, publicToken);
      if (!rec) return { ok: false, error: "条目不存在" };
      let data = null;
      try { data = JSON.parse(rec.content); } catch (_) { data = null; }
      if (!admin && data && data.ticket && data.ticket !== ticket) return { ok: false, error: "凭据不符" };
      const del = await ghJson(`/repos/${PUBLIC_REPO}/contents/public/${dir}/${f.name}`, publicToken, {
        method: "DELETE", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: `删除 ${(data && data.name) || f.name}`, sha: f.sha }),
      });
      if (!del.ok) return { ok: false, error: "删除失败" };
      if (type === "sound") {
        jdPurge(`public/${dir}/${f.name}`);
        try { await kvDelPrefix(["sndpub", ticket]); } catch (_) {}
      }
      const arr = (await pubIndex(type, publicToken)).filter((x) => x.ticket !== ticket);
      const w = await pubIndexWrite(type, publicToken, arr, `索引移除 ${ticket}`);
      if (!w.ok) return { ok: false, error: "索引更新失败" };
      return { ok: true, name: (data && data.name) || f.name };
    }
    // 采纳落款批量移除（与条目删除联动，保证各表一致）
    async function noticesRemoveTickets(tickets) {
      try {
        const acc = await ghRead(PUBLIC_REPO, "notices/accepted.json", publicToken);
        if (!acc) return { ok: true };
        const list = JSON.parse(acc.content);
        const before = list.length;
        const after = list.filter((x) => !tickets.includes(String(x.ticket || "")));
        if (after.length === before) return { ok: true };
        const w = await ghWrite(PUBLIC_REPO, "notices/accepted.json", publicToken, JSON.stringify(after), "删除采纳落款");
        return { ok: w.ok };
      } catch (_) { return { ok: true }; }
    }
    if (url.pathname === "/api/v1/public/delete" && req.method === "POST") {
      const b = await req.json();
      const type = String(b.type || "");
      const ticket = String(b.ticket || "").toLowerCase();
      if (!PUB_TYPES.includes(type) || !/^[a-z0-9]{32}$/.test(ticket)) return bad("参数无效");
      const isAdminOp = (req.headers.get("authorization") || "").indexOf(memberToken) >= 0;
      const r = await deletePubEntry(type, ticket, isAdminOp);
      if (!r.ok) return json({ ok: false, error: r.error }, 502);
      await noticesRemoveTickets([ticket]);
      return json({ ok: true });
    }
    if (url.pathname === "/api/v1/public/update" && req.method === "POST") {
      const b = await req.json();
      const type = String(b.type || "");
      const ticket = String(b.ticket || "").toLowerCase();
      const content = b.content;
      if (!PUB_TYPES.includes(type) || !/^[a-z0-9]{32}$/.test(ticket)) return bad("参数无效");
      if (!contentLooksValid(type, content)) return bad("内容格式校验未通过");
      const dir = PUB_DIRS[type];
      const lst = await ghJson(`/repos/${PUBLIC_REPO}/contents/public/${dir}`, publicToken);
      if (!lst.ok || !Array.isArray(lst.data)) return json({ ok: false, error: "读取失败" }, 502);
      const f = lst.data.find((x) => x.name.endsWith("-" + ticket.slice(0, 8) + ".json") && x.name !== "index.json");
      if (!f) return json({ ok: false, error: "条目不存在" }, 404);
      const rec = await ghRead(PUBLIC_REPO, `public/${dir}/${f.name}`, publicToken);
      if (!rec) return json({ ok: false, error: "条目不存在" }, 404);
      const data = JSON.parse(rec.content);
      if (data.ticket !== ticket) return json({ ok: false, error: "凭据不符" }, 403);
      data.content = content;
      const w = await ghWrite(PUBLIC_REPO, `public/${dir}/${f.name}`, publicToken, JSON.stringify(data), `更新 ${data.name}`);
      if (!w.ok) return json({ ok: false, error: "更新失败" }, 502);
      if (type === "sound") {
        jdPurge(`public/${dir}/${f.name}`);
        try { await kvSetBig(["sndpub", ticket], data, 7 * 86400_000); } catch (e) { console.error("SND KV UPDATE SET ERR", String(e)); }
      }
      return json({ ok: true });
    }

    // ---------- 音效中转（临时 · 读后即删 · 全量痕迹） ----------
    // 用途：自定义音效点对点/点对多点即时试听与提示音同步。
    // 音效本体仅私有账号仓临时文件 relay/{ticket}.json，10 分钟 TTL、读后即删，本体不留存（痕迹仍全量入公共仓 relay.json）
    const RELAY_TTL = 10 * 60 * 1000;
    async function relayLogAppend(entries) {
      try {
        const existing = await ghRead(PUBLIC_REPO, "notices/relay.json", publicToken);
        const list = existing ? JSON.parse(existing.content) : [];
        for (const e of entries) list.unshift({ id: genKey(), ...e });
        if (list.length > 500) list.length = 500;
        await ghWrite(PUBLIC_REPO, "notices/relay.json", publicToken, JSON.stringify(list), "领域动态·音效中转记录");
      } catch (_) { /* 记录失败不阻断中转 */ }
    }
    if (url.pathname === "/api/v1/sndrelay/put" && req.method === "POST") {
      const b = await req.json();
      const accountKey = String(b.accountKey || "");
      if (!/^[a-z0-9]{32}$/.test(accountKey)) return bad("凭据无效");
      const data = b.data;
      if (typeof data !== "string" || data.length === 0 || data.length > MAX_BODY) return bad("音效数据无效");
      const idx = await ghRead(MEMBER_REPO, `accounts/${accountKey}.json`, memberToken);
      if (!idx) return bad("账号不存在或凭据错误", 404);
      const rec = JSON.parse(idx.content);
      const sender = validName(b.senderName || "") ? b.senderName : (rec.playerName || "匿名");
      const name = String(b.name || "音效").slice(0, 64);
      const receivers = Array.isArray(b.receivers)
        ? b.receivers.map(r => String(r).slice(0, 32)).filter(Boolean).slice(0, 20) : [];
      const ticket = genKey();
      try {
        await ghWrite(MEMBER_REPO, "relay/" + ticket + ".json", memberToken,
          JSON.stringify({ name, data, senderName: sender, receivers, createdAt: Date.now() }), "relay put " + ticket.slice(0, 8));
      } catch (_) {
        return bad("中转写入失败，请重试");
      }
      relayLogAppend([{ t: "put", ts: new Date().toISOString(), sender, name, size: data.length, receivers, ticket8: ticket.slice(0, 8) }]);
      return json({ ok: true, ticket, expiresIn: 600 });
    }
    if (url.pathname === "/api/v1/sndrelay/get" && req.method === "GET") {
      const ticket = (url.searchParams.get("ticket") || "").toLowerCase();
      if (!/^[a-z0-9]{32}$/.test(ticket)) return bad("提取码无效");
      let r = null;
      const rf = await ghRead(MEMBER_REPO, "relay/" + ticket + ".json", memberToken);
      if (!rf) return json({ ok: false, error: "音效已过期或不存在" }, 404);
      try { r = JSON.parse(rf.content); } catch { r = null; }
      if (!r || (Date.now() - Number(r.createdAt || 0)) > RELAY_TTL) {
        await ghDelete(MEMBER_REPO, "relay/" + ticket + ".json", memberToken, "relay expired");
        return json({ ok: false, error: "音效已过期或不存在" }, 404);
      }
      await ghDelete(MEMBER_REPO, "relay/" + ticket + ".json", memberToken, "relay consumed");
      const receiver = String(url.searchParams.get("receiver") || "匿名").slice(0, 32);
      relayLogAppend([{ t: "get", ts: new Date().toISOString(), receiver, name: r.name, size: r.data.length, ticket8: ticket.slice(0, 8) }]);
      return json({ ok: true, name: r.name, senderName: r.senderName, data: r.data });
    }

    // ---------- 管理端：删除采纳记录（连带彻底删除公共库条目，删除后各表同步消失） ----------
    if (url.pathname === "/api/v1/admin/notice-delete" && req.method === "POST") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      const b = await req.json();
      const ticket = String(b.ticket || "").toLowerCase();
      if (!/^[a-z0-9]{32}$/.test(ticket)) return bad("ticket 无效");
      const acc = await ghRead(PUBLIC_REPO, "notices/accepted.json", publicToken);
      if (!acc) return json({ ok: false, error: "无采纳记录" }, 404);
      const list = JSON.parse(acc.content);
      const rec = list.find((x) => String(x.ticket || "") === ticket);
      if (!rec) return json({ ok: false, error: "记录不存在" }, 404);
      if (rec.type && PUB_TYPES.includes(rec.type)) {
        const r = await deletePubEntry(rec.type, ticket, true);
        if (!r.ok) return json({ ok: false, error: r.error }, 502);
      }
      const after = list.filter((x) => String(x.ticket || "") !== ticket);
      const w = await ghWrite(PUBLIC_REPO, "notices/accepted.json", publicToken, JSON.stringify(after), "删除采纳记录");
      if (!w.ok) return json({ ok: false, error: "写入失败" }, 502);
      return json({ ok: true });
    }

    // ---------- 管理端：删除音效中转记录 ----------
    if (url.pathname === "/api/v1/admin/relay-delete" && req.method === "POST") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      const b = await req.json();
      const id = String(b.id || "");
      if (!/^[a-z0-9]{32}$/.test(id)) return bad("id 无效");
      const acc = await ghRead(PUBLIC_REPO, "notices/relay.json", publicToken);
      if (!acc) return json({ ok: false, error: "无记录" }, 404);
      const list = JSON.parse(acc.content);
      const after = list.filter(x => x.id !== id);
      if (after.length === list.length) return json({ ok: false, error: "记录不存在" }, 404);
      const w = await ghWrite(PUBLIC_REPO, "notices/relay.json", publicToken, JSON.stringify(after), "删除中转记录");
      if (!w.ok) return json({ ok: false, error: "写入失败" }, 502);
      return json({ ok: true });
    }

    // ---------- 管理端：解除玩家名绑定（改名 / 误绑时用） ----------
    // 背景：注册时「一个玩家名只能属于一个 uuid」，用于防止他人抢注你的名字冒用投稿落款。
    // 玩家真的改名或换号时，由作者在这里解绑旧名字。
    if (url.pathname === "/api/v1/admin/name-bind" && req.method === "GET") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      const nm = String(url.searchParams.get("name") || "").trim();
      if (!validName(nm)) return bad("玩家名无效");
      const bind = await ghRead(MEMBER_REPO, `names/${nm.toLowerCase()}.json`, memberToken);
      if (!bind) return json({ ok: true, bound: false, name: nm });
      let rec = {};
      try { rec = JSON.parse(bind.content); } catch (_) {}
      return json({ ok: true, bound: true, name: nm, uuid: rec.uuid || "", boundAt: rec.boundAt || "" });
    }
    if (url.pathname === "/api/v1/admin/name-unbind" && req.method === "POST") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      const b = await req.json();
      const nm = String((b && b.name) || "").trim();
      if (!validName(nm)) return bad("玩家名无效");
      const rec = await ghRead(MEMBER_REPO, `names/${nm.toLowerCase()}.json`, memberToken);
      if (!rec) return json({ ok: false, error: "该名字没有绑定记录" }, 404);
      const del = await ghJson(`/repos/${MEMBER_REPO}/contents/names/${nm.toLowerCase()}.json`, memberToken, {
        method: "DELETE", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: `解绑玩家名 ${nm}`, sha: rec.sha }),
      });
      return json({ ok: !!del.ok, name: nm });
    }

    // ---------- 管理端：食材元素库授权上传者名单 ----------
    if (url.pathname === "/api/v1/admin/uploaders" && req.method === "GET") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      return json({ ok: true, names: await uploaderList(publicToken), uuids: (await uploaderAuth(publicToken)).uuids });
    }
    if (url.pathname === "/api/v1/admin/uploaders/add" && req.method === "POST") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      const b = await req.json();
      const nm = String(b.name || "").trim();
      if (!validName(nm)) return bad("玩家名无效");
      const cur = await uploaderAuth(publicToken);
      if (!cur.names.includes(nm)) cur.names.push(nm);
      // uuid 才是硬身份：优先用管理员传入的，其次用该玩家名已绑定的账号 uuid
      let uu = String(b.uuid || "").trim().toLowerCase();
      if (!validUuid(uu)) {
        const bind = await ghRead(MEMBER_REPO, `names/${nm.toLowerCase()}.json`, memberToken);
        if (bind) {
          try { uu = String(JSON.parse(bind.content).uuid || "").toLowerCase(); } catch (_) {}
        }
      }
      if (validUuid(uu) && !cur.uuids.includes(uu)) cur.uuids.push(uu);
      const w = await uploaderWrite(publicToken, cur.names, cur.uuids);
      if (!w.ok) return json({ ok: false, error: "名单写入失败" }, 502);
      return json({ ok: true, names: cur.names, uuids: cur.uuids });
    }
    if (url.pathname === "/api/v1/admin/uploaders/remove" && req.method === "POST") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      const b = await req.json();
      const nm = String(b.name || "").trim();
      const au = await uploaderAuth(publicToken);
      const cur = au.names.filter((x) => x !== nm);
      let uu = String(b.uuid || "").trim().toLowerCase();
      if (!validUuid(uu)) {
        const bind = await ghRead(MEMBER_REPO, `names/${nm.toLowerCase()}.json`, memberToken);
        if (bind) {
          try { uu = String(JSON.parse(bind.content).uuid || "").toLowerCase(); } catch (_) {}
        }
      }
      const uuids = validUuid(uu) ? au.uuids.filter((x) => x !== uu) : au.uuids;
      const w = await uploaderWrite(publicToken, cur, uuids);
      if (!w.ok) return json({ ok: false, error: "名单写入失败" }, 502);
      return json({ ok: true, names: cur, uuids });
    }

    // ---------- 管理端：批量删除（多选） ----------
    // kind: "notice"（按 ticket，连带删公共库条目）| "public"（items=[{type,ticket}]）| "relay"（items=[id]）
    if (url.pathname === "/api/v1/admin/batch-delete" && req.method === "POST") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      const b = await req.json();
      const kind = String(b.kind || "");
      const failed = [];
      let deleted = 0;
      if (kind === "relay") {
        const ids = Array.isArray(b.items) ? b.items.map(String).filter((x) => /^[a-z0-9]{32}$/.test(x)) : [];
        const acc = await ghRead(PUBLIC_REPO, "notices/relay.json", publicToken);
        if (!acc) return json({ ok: false, error: "无记录" }, 404);
        const list = JSON.parse(acc.content);
        const after = list.filter((x) => !ids.includes(String(x.id || "")));
        deleted = list.length - after.length;
        const w = await ghWrite(PUBLIC_REPO, "notices/relay.json", publicToken, JSON.stringify(after), "批量删除中转记录");
        if (!w.ok) return json({ ok: false, error: "写入失败" }, 502);
      } else if (kind === "notice") {
        const tickets = Array.isArray(b.items) ? b.items.map((x) => String(x).toLowerCase()).filter((x) => /^[a-z0-9]{32}$/.test(x)) : [];
        const acc = await ghRead(PUBLIC_REPO, "notices/accepted.json", publicToken);
        if (!acc) return json({ ok: false, error: "无采纳记录" }, 404);
        const list = JSON.parse(acc.content);
        for (const ticket of tickets) {
          const rec = list.find((x) => String(x.ticket || "") === ticket);
          if (!rec) continue;
          if (rec.type && PUB_TYPES.includes(rec.type)) {
            const r = await deletePubEntry(rec.type, ticket, true);
            if (r.ok) deleted++; else failed.push(ticket.slice(0, 8) + ":" + r.error);
          } else deleted++;
        }
        const after = list.filter((x) => !tickets.includes(String(x.ticket || "")));
        const w = await ghWrite(PUBLIC_REPO, "notices/accepted.json", publicToken, JSON.stringify(after), "批量删除采纳记录");
        if (!w.ok) return json({ ok: false, error: "落款写入失败" }, 502);
      } else if (kind === "public") {
        const items = Array.isArray(b.items) ? b.items : [];
        const removedTickets = [];
        const seen = new Set();
        for (const it of items) {
          const type = String(it && it.type || "");
          const ticket = String(it && it.ticket || "").toLowerCase();
          if (!PUB_TYPES.includes(type) || !/^[a-z0-9]{32}$/.test(ticket) || seen.has(type + "|" + ticket)) continue;
          seen.add(type + "|" + ticket);
          const r = await deletePubEntry(type, ticket, true);
          if (r.ok) { deleted++; removedTickets.push(ticket); } else failed.push(ticket.slice(0, 8) + ":" + r.error);
        }
        await noticesRemoveTickets(removedTickets);
      } else return bad("kind 无效");
      return json({ ok: true, deleted, failed });
    }

    // ---------- 管理端：编辑公共投稿（内容与类型；时间与投稿人保持不变） ----------
    // 可改：name / content / type（跨类型自动迁移文件与索引）。
    // 不可改：ticket / senderName / acceptedAt（投稿人落款与入库时间原样保留），likes 以索引为准不重置。
    if (url.pathname === "/api/v1/admin/edit" && req.method === "POST") {
      const auth = req.headers.get("authorization") || "";
      if (auth !== "Bearer " + memberToken) return json({ ok: false, error: "无权限" }, 403);
      const b = await req.json();
      const type = String(b.type || "");
      const newType = String(b.newType || type);
      const ticket = String(b.ticket || "").toLowerCase();
      const name = String(b.name || "").trim();
      const content = b.content;
      // 可选：改投稿人落款；不传则保留原 senderName；时间戳 acceptedAt 永远保留不动
      const newSender = (b.senderName != null) ? String(b.senderName).trim() : null;
      if (newSender !== null && !validName(newSender)) return bad("投稿人名称无效");
      if (!PUB_TYPES.includes(type) || !PUB_TYPES.includes(newType)) return bad("类型无效");
      if (!/^[a-z0-9]{32}$/.test(ticket)) return bad("ticket 无效");
      if (!validName(name)) return bad("名称无效");
      if (!contentLooksValid(newType, content)) return bad("内容格式校验未通过");
      const dir = PUB_DIRS[type];
      const lst = await ghJson(`/repos/${PUBLIC_REPO}/contents/public/${dir}`, publicToken);
      if (!lst.ok || !Array.isArray(lst.data)) return json({ ok: false, error: "读取失败" }, 502);
      const f = lst.data.find((x) => x.name.endsWith("-" + ticket.slice(0, 8) + ".json") && x.name !== "index.json");
      if (!f) return json({ ok: false, error: "条目不存在" }, 404);
      const rec = await ghRead(PUBLIC_REPO, `public/${dir}/${f.name}`, publicToken);
      if (!rec) return json({ ok: false, error: "条目不存在" }, 404);
      const data = JSON.parse(rec.content);
      if (data.ticket !== ticket) return json({ ok: false, error: "凭据不符" }, 403);
      const safeName = name.replace(/[^\w\u4e00-\u9fa5-]+/g, "_");
      const oldPath = `public/${dir}/${f.name}`;
      const newPath = `public/${PUB_DIRS[newType]}/${safeName}-${ticket.slice(0, 8)}.json`;
      const updated = { ...data, type: newType, name, content };
      if (newSender !== null) updated.senderName = newSender;
      const effectiveSender = updated.senderName || "匿名";
      if (newPath === oldPath) {
        const w = await ghWrite(PUBLIC_REPO, oldPath, publicToken, JSON.stringify(updated), `编辑 ${type}: ${name}`);
        if (!w.ok) return json({ ok: false, error: "更新失败" }, 502);
      } else {
        const wn = await ghWrite(PUBLIC_REPO, newPath, publicToken, JSON.stringify(updated), `编辑迁移 ${newType}: ${name}`);
        if (!wn.ok) return json({ ok: false, error: "写入失败" }, 502);
        const del = await ghJson(`/repos/${PUBLIC_REPO}/contents/${oldPath}`, publicToken, {
          method: "DELETE", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ message: `编辑迁移清理 ${f.name}`, sha: f.sha }),
        });
        if (!del.ok) return json({ ok: false, error: "旧条目清理失败" }, 502);
        if (type === "sound") jdPurge(oldPath);
      }
      // 音效缓存（旧路径已清；新旧均刷新 jsDelivr + KV）
      if (type === "sound" || newType === "sound") {
        jdPurge(newPath);
        try { await kvSetBig(["sndpub", ticket], updated, 7 * 86400_000); } catch (e) { console.error("SND KV EDIT SET ERR", String(e)); }
      }
      // 索引：原类型移除，新类型插入（保留 likes 与 acceptedAt/senderName）
      const oldIdx = await pubIndex(type, publicToken);
      const m0 = oldIdx.find((x) => x.ticket === ticket);
      const likes = m0 ? Number(m0.likes || 0) : 0;
      const oa = oldIdx.filter((x) => x.ticket !== ticket);
      const wo = await pubIndexWrite(type, publicToken, oa, `索引编辑移除 ${ticket}`);
      if (!wo.ok) return json({ ok: false, error: "旧索引更新失败" }, 502);
      const ni = await pubIndex(newType, publicToken);
      ni.unshift({ v: 1, ticket, type: newType, name, senderName: effectiveSender, acceptedAt: data.acceptedAt, likes });
      if (ni.length > 1000) ni.length = 1000;
      const wn2 = await pubIndexWrite(newType, publicToken, ni, `索引编辑 ${newType}: ${name}`);
      if (!wn2.ok) return json({ ok: false, error: "新索引更新失败" }, 502);
      // 采纳清单同步（落款时间与投稿人原样保留）
      try {
        const acc = await ghRead(PUBLIC_REPO, "notices/accepted.json", publicToken);
        if (acc) {
          const list = JSON.parse(acc.content);
          const i = list.findIndex((x) => String(x.ticket || "") === ticket);
          if (i >= 0) { list[i].type = newType; list[i].name = name; list[i].senderName = effectiveSender; }
          await ghWrite(PUBLIC_REPO, "notices/accepted.json", publicToken, JSON.stringify(list), `采纳落款编辑 ${newType}: ${name}`);
        }
      } catch (_) {}
      // 元素库 all.json 聚合同步：编辑后保持与单文件一致（时间戳沿用 data.acceptedAt，不刷新）
      if (type === "element" || newType === "element") {
        try {
          const allRec = await ghRead(PUBLIC_REPO, "public/elements/all.json", publicToken);
          let allArr = allRec ? JSON.parse(allRec.content) : [];
          if (!Array.isArray(allArr)) allArr = [];
          allArr = allArr.filter((x) => x.ticket !== ticket);
          if (newType === "element") allArr.push(updated);
          await ghWrite(PUBLIC_REPO, "public/elements/all.json", publicToken, JSON.stringify(allArr), `编辑聚合元素库: ${name}`);
          try { await kvDelPrefix(["elements-all"]); } catch (_) {}
        } catch (e) { console.error("EDIT ALLJSON ERR", String(e)); }
      }
      return json({ ok: true });
    }
    if (url.pathname === "/api/v1/kvcheck" && req.method === "GET") {
      const isA = req.headers.get("authorization") === "Bearer " + memberToken || url.searchParams.get("t") === memberToken;
      if (!isA) return json({ ok: false, error: "无权限" }, 403);
      const t0 = Date.now();
      try {
        const k = "kvcheck-" + crypto.randomUUID().replace(/-/g, "");
        await kvSet([k], { hello: "world", at: Date.now() }, { expireIn: 60_000 });
        const r = await kvGet([k]);
        await kvDelete([k]);
        const big = "A".repeat(200_000);
        const t1 = Date.now();
        await kvSetBig(["kvcheck-big"], { data: big });
        const back = await kvGetBig(["kvcheck-big"]);
        const bigOk = !!(back && back.data && back.data.length === 200_000);
        await kvDelPrefix(["kvcheck-big"]);
        return json({ ok: true, latency: Date.now() - t0, read: r && r.value ? r.value.hello : null, bigOk, bigLatency: Date.now() - t1 });
      } catch (e) {
        console.error("KVCHECK", e);
        return json({ ok: false, error: String((e && e.message) || e), latency: Date.now() - t0 }, 500);
      }
    }

    // ---------- 后台数据（管理端）----------
    const isAdmin = req.headers.get("authorization") === "Bearer " + memberToken
      || url.searchParams.get("t") === memberToken;
    if (url.pathname === "/api/v1/diag" && req.method === "GET") {
      if (!isAdmin) return json({ ok: false, error: "无权限" }, 403);
      const out = {};
      const t0 = Date.now();
      const ghR = await ghJson("/rate_limit", publicToken);
      let ghBody = null;
      try { ghBody = typeof ghR.data === "string" ? ghR.data.slice(0, 400) : JSON.stringify(ghR.data || null).slice(0, 400); } catch (_) {}
      out.github = { status: ghR.status, ok: ghR.ok, err: ghR.err || null, body: ghBody };
      const jd = await jdRead("notices/accepted.json");
      out.jsdelivr = jd ? { ok: true, len: jd.length } : { ok: false };
      out.ms = Date.now() - t0;
      return json({ ok: true, ...out });
    }
    if (url.pathname === "/api/v1/admin/stats" && req.method === "GET") {
      if (!isAdmin) return json({ ok: false, error: "无权限" }, 403);
      const [acc, pendDir, fD, rD, hD, sD, eD] = await Promise.all([
        ghRead(PUBLIC_REPO, "notices/accepted.json", publicToken),
        ghJson(`/repos/${PUBLIC_REPO}/contents/pending`, publicToken),
        ghJson(`/repos/${PUBLIC_REPO}/contents/public/foods`, publicToken),
        ghJson(`/repos/${PUBLIC_REPO}/contents/public/recipes`, publicToken),
        ghJson(`/repos/${PUBLIC_REPO}/contents/public/halves`, publicToken),
        ghJson(`/repos/${PUBLIC_REPO}/contents/public/sounds`, publicToken),
        ghJson(`/repos/${PUBLIC_REPO}/contents/public/elements`, publicToken),
      ]);
      const accList = acc ? JSON.parse(acc.content) : [];
      const counts = { food: 0, recipe: 0, half: 0, sound: 0, element: 0 };
      const latest = [];
      const dirMeta = [
        [fD, "foods", "food"],
        [rD, "recipes", "recipe"],
        [hD, "halves", "half"],
        [sD, "sounds", "sound"],
        [eD, "elements", "element"],
      ];
      const pubItems = [];
      const idxResults = await Promise.all(dirMeta.map(async ([d, dirName, key]) => {
        const out = [];
        if (d.ok && Array.isArray(d.data)) {
          for (const f of d.data) {
            if (f.name === "index.json") continue;
            counts[key]++;
            if (latest.length < 12) latest.push({ path: dirName + "/" + f.name, size: f.size, name: f.name });
          }
        }
        try {
          const idx = await pubIndex(key, publicToken);
          for (const it of idx) out.push({ ticket: it.ticket, type: key, name: it.name || "?", senderName: it.senderName || "匿名", likes: Number(it.likes || 0), acceptedAt: it.acceptedAt || "" });
        } catch (_) { }
        return out;
      }));
      for (const arr of idxResults) pubItems.push(...arr);
      pubItems.sort((a, b) => (String(b.acceptedAt) < String(a.acceptedAt) ? -1 : 1));
      let pendingList = [];
      let pendingCount = 0;
      if (pendDir.ok && Array.isArray(pendDir.data)) {
        const tickets = pendDir.data.filter((x) => x.name !== ".gitkeep").slice(0, 20);
        pendingCount = tickets.length;
        pendingList = (await Promise.all(tickets.map(async (x) => {
          const p = await ghRead(PUBLIC_REPO, "pending/" + x.name, publicToken);
          if (!p) return null;
          try {
            const it = JSON.parse(p.content);
            return { ticket: x.name.replace(/\.json$/, ""), type: it.type || "?", name: it.name || "?", senderName: it.senderName || "匿名" };
          } catch {
            return { ticket: x.name.replace(/\.json$/, ""), type: "?", name: x.name, senderName: "?" };
          }
        }))).filter(Boolean);
      }
      const fileCount = counts.food + counts.recipe + counts.half + counts.sound + counts.element;
      let relayLog = [];
      try {
        const rl = await ghRead(PUBLIC_REPO, "notices/relay.json", publicToken);
        if (rl) relayLog = JSON.parse(rl.content).slice(0, 50);
      } catch (_) { }
      const uploaders = await uploaderList(publicToken);
      return json({ ok: true, counts, fileCount, latest, notices: accList.slice(0, 50), pendingCount, pendingList, publicItems: pubItems.slice(0, 200), relayLog, uploaders });
    }
    if (url.pathname === "/admin" && req.method === "GET") {
      if (!isAdmin) return new Response("403 Forbidden", { status: 403 });
      return new Response(adminPage(url.searchParams.get("t") || ""), {
        headers: { "content-type": "text/html; charset=utf-8" },
      });
    }

    return bad("未知路由", 404);
  } catch (e) {
    return json({ ok: false, error: "端点异常: " + String(e) }, 500);
  }
};

