<script>
  const t = ${JSON.stringify(token)};
  let pvType = "", pvTicket = "", pvBody = "";
  function closePreview() { document.getElementById("preview").style.display = "none"; document.getElementById("pvPlay").style.display = "none"; }
  function playPreview() {
    if (!pvBody) return;
    try {
      const audio = new Audio("data:audio/wav;base64," + pvBody);
      audio.play().catch(e => alert("试听失败：" + e.message));
    } catch (e) { alert("试听失败：" + e.message); }
  }
  function showPreview(title, type, ticket, body) {
    pvType = type; pvTicket = ticket; pvBody = body;
    document.getElementById("pvTitle").textContent = title;
    document.getElementById("pvBody").textContent = body;
    document.getElementById("pvPlay").style.display = type === "sound" && body ? "inline-block" : "none";
    document.getElementById("preview").style.display = "block";
  }
  async function refresh() {
    try {
      const r = await fetch("/api/v1/admin/stats" + (t ? "?t=" + encodeURIComponent(t) : ""), { cache: "no-store" });
      const d = await r.json();
      if (!d.ok) { document.getElementById("fresh").textContent = "接口错误：" + (d.error || "未知"); return; }
      document.getElementById("fresh").textContent = "更新于 " + new Date().toLocaleTimeString();
      document.getElementById("cTotal").textContent = d.fileCount;
      document.getElementById("cFood").textContent = d.counts.food;
      document.getElementById("cRecipe").textContent = d.counts.recipe;
      document.getElementById("cHalf").textContent = d.counts.half;
      document.getElementById("cSound").textContent = d.counts.sound;
      document.getElementById("cElement").textContent = d.counts.element;
      document.getElementById("cNotice").textContent = d.notices.length;
      document.getElementById("cPending").textContent = d.pendingCount;
      const ul = document.getElementById("upList");
      ul.innerHTML = (d.uploaders || []).map(n =>
        "<span style='display:inline-block;border:1px solid #9fd8cf;border-radius:20px;padding:2px 10px;margin:2px 6px 2px 0;font-size:12px;color:#0f6a58;background:#f0fbf8;'>" + esc(n) +
        " <a href='#' data-rm='" + esc(n) + "' style='color:#a14e50;text-decoration:none;'>✕</a></span>").join("") ||
        "<span class='muted'>暂无授权玩家（作者本人可先添加自己）</span>";
      const fb = document.getElementById("files");
      fb.innerHTML = (d.latest || []).map(f => "<tr><td>" + esc(f.path) + "</td><td>" + (f.size / 1024).toFixed(1) + " KB</td></tr>").join("");
      const nb = document.getElementById("notices");
      nb.innerHTML = (d.notices || []).map(n =>
        "<tr><td><input type='checkbox' class='sel' data-set='notices' data-v='" + esc(n.ticket) + "'></td>" +
        "<td>" + esc(cnTime(n.acceptedAt)) + "</td>" +
        "<td><span class='tag " + (n.type === "sound" ? "sound" : n.type === "food" ? "food" : "") + "'>" + esc(n.type) + "</span></td>" +
        "<td>" + esc(n.name) + "</td><td>" + esc(n.senderName || "匿名") + "</td>" +
        "<td><button class='danger' data-act='delnotice' data-t='" + esc(n.ticket) + "'>删除</button></td></tr>").join("") ||
        "<tr><td colspan='6' class='muted'>暂无采纳记录</td></tr>";
      const pub = document.getElementById("pubitems");
      pub.innerHTML = (d.publicItems || []).map(n =>
        "<tr><td><input type='checkbox' class='sel' data-set='pub' data-type='" + n.type + "' data-v='" + esc(n.ticket) + "'></td>" +
        "<td><span class='tag " + (n.type === "sound" ? "sound" : n.type === "food" ? "food" : "") + "'>" + esc(n.type) + "</span></td>" +
        "<td>" + esc(n.name) + "</td><td>" + esc(n.senderName) + "</td>" +
        "<td>" + esc(cnTime(n.acceptedAt)) + "</td><td>♥" + n.likes + "</td>" +
        "<td><button data-act='view' data-type='" + n.type + "' data-t='" + esc(n.ticket) + "'>查看</button> <button data-act='editpub' data-type='" + n.type + "' data-t='" + esc(n.ticket) + "'>编辑</button> <button class='danger' data-act='delpub' data-type='" + n.type + "' data-t='" + esc(n.ticket) + "'>删除</button></td></tr>").join("") ||
        "<tr><td colspan='7' class='muted'>公共库暂无数据</td></tr>";
      const rb = document.getElementById("relay");
      rb.innerHTML = (d.relayLog || []).map(n => {
        const who = n.t === "put" ? esc(n.sender || "") : ("→ " + esc(n.receiver || ""));
        const act = n.t === "put" ? "上传中转" : "拉取播放";
        return "<tr><td><input type='checkbox' class='sel' data-set='relay' data-v='" + esc(n.id) + "'></td>" +
          "<td>" + esc(cnTime(n.ts)) + "</td>" +
          "<td><span class='tag'>" + act + "</span></td><td>" + esc(n.sender || "-") + "</td><td>" + esc(n.receiver || (n.receivers || []).join("、") || "-") + "</td>" +
          "<td>" + esc(n.name) + "</td><td>" + Math.round((n.size || 0) * 0.75 / 1024) + " KB</td>" +
          "<td><button class='danger' data-act='delrelay' data-id='" + esc(n.id) + "'>删除</button></td></tr>";
      }).join("") ||
        "<tr><td colspan='8' class='muted'>暂无中转记录（玩家分享自定义音效后会出现）</td></tr>";
      const pb = document.getElementById("pending");
      pb.innerHTML = (d.pendingList || []).map(n =>
        "<tr><td><span class='tag " + (n.type === "sound" ? "sound" : n.type === "food" ? "food" : "") + "'>" + esc(n.type) + "</span></td>" +
        "<td>" + esc(n.name) + "</td><td>" + esc(n.senderName) + "</td>" +
        "<td><button data-act='accept' data-t='" + esc(n.ticket) + "'>采纳</button> <button class='danger' data-act='del' data-t='" + esc(n.ticket) + "'>删除</button></td></tr>").join("") ||
        "<tr><td colspan='4' class='muted'>无待审</td></tr>";
      selUpdate();
    } catch (e) {
      document.getElementById("fresh").textContent = "刷新失败：" + e.message;
    }
  }
  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }
  function cnTime(s) { if (!s) return ""; var dt = new Date(s); if (isNaN(dt.getTime())) return ""; return dt.toLocaleString("zh-CN", { hour12: false, timeZone: "Asia/Shanghai" }); }
  async function viewPub(type, ticket) {
    try {
      const r = await fetch("/api/v1/public/get?type=" + encodeURIComponent(type) + "&ticket=" + encodeURIComponent(ticket), { cache: "no-store" });
      const d = await r.json();
      if (!d.ok) { alert("读取失败：" + (d.error || r.status)); return; }
      const it = d.item || {};
      let body = String(it.content == null ? "" : it.content);
      if (type === "sound") {
        showPreview("【音效】" + (it.name || "") + "　投稿者：" + (it.senderName || "匿名"), type, ticket, "音效数据：base64 " + body.length + " 字符（约 " + Math.round(body.length * 0.75 / 1024) + " KB）\\n点击上方「试听」可先听效果");
        return;
      }
