// 食材元素库种子：首次部署时自动播种（幂等，index 已存在则跳过）。
// 数据源与模组内置食材库同源（tianhaizi 内置数据）：未测量元素值的只录效果。
// 之后由后台授权的玩家通过 element-upload 持续更新（同名最新覆盖）。
async function seedElements(publicToken) {
  const dir = PUB_DIRS.element;
  const existing = await ghRead(PUBLIC_REPO, `public/${dir}/index.json`, publicToken);
  if (existing) {
    try { if (JSON.parse(existing.content).length >= ELEMENT_SEED.length) return; } catch (_) {}
  }
  // 已有 all.json 时按名称保留原署名（wenzn/tianhaizi/Clyinton），避免重播种把署名覆盖为单一作者
  const prevByName = new Map();
  const prevAll = await ghRead(PUBLIC_REPO, `public/${dir}/all.json`, publicToken);
  if (prevAll) { try { const _p = JSON.parse(prevAll.content); for (const _x of _p) prevByName.set(String(_x.name || ""), String(_x.senderName || "")); } catch (_) {} }
  const arr = [];
  const allItems = [];
  for (const s of ELEMENT_SEED) {
    const ticket = genKey();
    const content = JSON.stringify({ name: s.name, elements: s.elements || {}, data: [s] });
    const sn = prevByName.get(String(s.name || "")) || "tianhaizi";
    const item = { v: 1, ticket, type: "element", name: s.name, content, senderName: sn, acceptedAt: new Date().toISOString() };
    arr.push({ v: 1, ticket, type: "element", name: s.name, senderName: sn, acceptedAt: item.acceptedAt, likes: 0 });
    allItems.push(item);
  }
  // 种子 152 条合并为单个 all.json 一次写入（规避 CF 免费版 50 子请求上限），索引单独写入
  const w = await ghWrite(PUBLIC_REPO, `public/${dir}/all.json`, publicToken, JSON.stringify(allItems), "元素库种子数据");
  if (!w.ok) return;
  await pubIndexWrite("element", publicToken, arr, "元素库种子索引");
}// 定时预热：每 5 分钟预热公共索引缓存(并顺带把热门数据落到本地)
async function warm() {
  try {
    const t0 = Date.now();
    const publicToken = ENV.PUBLIC_TOKEN;
    // 预热各分区索引 + 采纳清单到内存缓存
    await Promise.all(
      ["food", "recipe", "half", "sound", "element"].map((type) => pubIndex(type, publicToken))
    );
    await ghRead(PUBLIC_REPO, "notices/accepted.json", publicToken);
    try { await seedElements(publicToken); } catch (e) { console.error("SEED ERR " + String(e)); }
    console.error("WARM OK ms=" + (Date.now() - t0));
  } catch (e) {
    console.error("WARM ERR " + String(e));
  }
}


// ================= Node 本地存储层 =================
const APP_DIR = path.dirname(fileURLToPath(import.meta.url));
function localPath(repo, p) {
  const safeRepo = String(repo).replace(/[^\w-]/g, "_");
  const parts = String(p).split("/").map((x) => x.replace(/\.\./g, "_"));
  return path.join(ENV.DATA_DIR, "store", safeRepo, ...parts);
}
function sha1hex(content) {
  return createHash("sha1").update(content).digest("hex");
}
async function localWrite(lp, content) {
  await fsp.mkdir(path.dirname(lp), { recursive: true });
  const tmp = lp + "." + Date.now() + ".tmp";
  await fsp.writeFile(tmp, content, "utf8");
  await fsp.rename(tmp, lp);
}
async function localDelete(lp) {
  try { await fsp.unlink(lp); } catch (_) {}
}
// 目录列表合并缓存:30 秒内秒回本地,过期/首次时并拉远端补齐(meta)
const dirMergeCache = new Map();
// 本地分派:GET 文件/目录本地优先;PUT/DELETE 本地落盘 + 异步备份 GitHub
async function localDispatch(p, token, init, remoteFn) {
  const method = (init.method || "GET").toUpperCase();
  if (p === "/rate_limit") {
    return { status: 200, ok: true, data: { resources: { core: { limit: 5000, remaining: 5000, reset: Math.floor(Date.now() / 1000) + 3600 } } } };
  }
  const m = /^\/repos\/([^/]+)\/([^/]+)\/contents\/(.*)$/.exec(p);
  if (!m) return null;
  const repo = m[1] + "/" + m[2];
  let rest = m[3] || "";
  try { rest = decodeURIComponent(rest); } catch (_) {}
  const tk = /members$/.test(repo) ? ENV.MEMBER_TOKEN : ENV.PUBLIC_TOKEN;
  if (method === "GET") {
    // 按本地类型识别:文件→读内容;目录→列目录(30s 合并远端 meta)
    const lp = localPath(repo, rest);
    let isDir = false;
    try {
      const st = await fsp.stat(lp);
      if (st.isFile()) {
        const content = await fsp.readFile(lp, "utf8");
        return { status: 200, ok: true, data: { sha: sha1hex(content), size: Buffer.byteLength(content), content: toB64(content), encoding: "base64" } };
      }
      if (st.isDirectory()) isDir = true;
    } catch (_) {}
    if (isDir) {
      const localList = [];
      try {
        const names = await fsp.readdir(lp);
        for (const n of names.sort()) {
          try {
            const st2 = await fsp.stat(path.join(lp, n));
            localList.push({ name: n, sha: "local-" + st2.size + "-" + Math.floor(st2.mtimeMs), size: st2.size });
          } catch (_) {}
        }
      } catch (_) { return null; }
      const key = "dirmerge|" + p;
      const last = dirMergeCache.get(key);
      if (!last || Date.now() - last > 30000) {
        const remote = await remoteFn(p, tk, { method: "GET" }).catch(() => null);
        if (remote && remote.ok && Array.isArray(remote.data)) {
          dirMergeCache.set(key, Date.now());
          if (dirMergeCache.size > 512) { for (const k of dirMergeCache.keys()) { if (dirMergeCache.size <= 256) break; dirMergeCache.delete(k); } }
          const byName = new Map(localList.map((f) => [f.name, f]));
          for (const rf of remote.data) {
            if (rf.name === "index.json" && !byName.has(rf.name)) localList.unshift({ name: rf.name, sha: rf.sha, size: rf.size });
            else if (!byName.has(rf.name)) localList.push({ name: rf.name, sha: rf.sha, size: rf.size });
          }
        }
      }
      return { status: 200, ok: true, data: localList };
    }
    return null; // 本地 miss → 回源(ghRemote 会落盘)
  }
  if (method === "PUT") {
    let body = {};
    try { body = JSON.parse(String(init.body || "{}")); } catch (_) {}
    const content = fromB64(String(body.content || ""));
    await localWrite(localPath(repo, rest), content);
    // 异步备份 GitHub(不阻塞响应)
    remoteFn(p, tk, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) })
      .catch((e) => console.error("GH BACKUP PUT ERR " + p + " " + String(e)));
    return { status: 201, ok: true, data: { content: { sha: sha1hex(content) } } };
  }
  if (method === "DELETE") {
    await localDelete(localPath(repo, rest));
    remoteFn(p, tk, { method: "DELETE", headers: { "Content-Type": "application/json" }, body: String(init.body || "{}") })
      .catch((e) => console.error("GH BACKUP DEL ERR " + p + " " + String(e)));
    return { status: 200, ok: true, data: null };
  }
  return null;
}
// 回源成功后落盘(懒迁移):文件写正文,目录仅建目录
async function localStoreRemote(p, d) {
  const m = /^\/repos\/([^/]+)\/([^/]+)\/contents\/(.*)$/.exec(p);
  if (!m) return;
  const repo = m[1] + "/" + m[2];
  let rest = m[3] || "";
  try { rest = decodeURIComponent(rest); } catch (_) {}
  if (Array.isArray(d)) {
    try { await fsp.mkdir(localPath(repo, rest), { recursive: true }); } catch (_) {}
    return;
  }
  if (d && typeof d.content === "string") {
    try { await localWrite(localPath(repo, rest), fromB64(d.content)); } catch (_) {}
  }
}

// ================= 更新机制 =================
let SERVER_VERSION = "1.0.5";
async function applyUpdate(version, code) {
  if (!/^[0-9A-Za-z.\-_]{1,32}$/.test(version)) return { ok: false, error: "版本号无效" };
  if (typeof code !== "string" || code.length === 0 || code.length > 4 * 1024 * 1024) return { ok: false, error: "代码无效或过大" };
  const updDir = path.join(ENV.DATA_DIR, "updates");
  await fsp.mkdir(updDir, { recursive: true });
  const incoming = path.join(updDir, "incoming-" + version + ".mjs");
  await fsp.writeFile(incoming, code, "utf8");
  try {
    execFileSync(process.execPath, ["--check", incoming], { stdio: "pipe" });
  } catch (e) {
    try { await fsp.unlink(incoming); } catch (_) {}
    return { ok: false, error: "新版本语法校验未通过" };
  }
  const cur = path.join(APP_DIR, "server.mjs");
  const bak = path.join(updDir, "server-" + SERVER_VERSION + "-" + Date.now() + ".mjs");
  try { await fsp.copyFile(cur, bak); } catch (_) {}
  try {
    await fsp.rename(incoming, cur);
  } catch (e) {
    try { await fsp.copyFile(bak, cur); } catch (_) {}
    return { ok: false, error: "替换失败: " + String(e) };
  }
  SERVER_VERSION = version;
  try {
    await fsp.appendFile(path.join(ENV.DATA_DIR, "updates.log"),
      JSON.stringify({ ts: new Date().toISOString(), version, result: "ok" }) + "\n");
  } catch (_) {}
  console.error("UPDATE OK -> " + version);
  return { ok: true };
}
async function handleUpdate(req, body, res) {
  const u = new URL(req.url, "http://localhost");
  const tok = req.headers["x-deploy-token"] || u.searchParams.get("t") || "";
  if (!ENV.DEPLOY_TOKEN || tok !== ENV.DEPLOY_TOKEN) {
    res.writeHead(403, { "content-type": "application/json; charset=utf-8" });
    res.end(JSON.stringify({ ok: false, error: "无权限" })); return;
  }
  let b = null;
  try { b = JSON.parse(body.toString("utf8")); } catch (_) {}
  if (!b || typeof b.version !== "string" || typeof b.code !== "string") {
    res.writeHead(400, { "content-type": "application/json; charset=utf-8" });
    res.end(JSON.stringify({ ok: false, error: "参数无效(需要 version + code)" })); return;
  }
  const r = await applyUpdate(b.version, b.code);
  res.writeHead(r.ok ? 200 : 500, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify({ ok: r.ok, error: r.error || null, version: b.version }));
  if (r.ok) setTimeout(() => process.exit(0), 500); // systemd/docker 自动拉起新版本
}
// 定时兜底:每 5 分钟查版本源,有新版本自动升级
// 版本源按顺序尝试:Worker 端点(国内可达) → 环境变量指定 → jsDelivr(可能被墙)
async function autoUpdateCheck() {
  if (ENV.AUTO_UPDATE === "false") return;
  const sources = [];
  const push = (u) => { const s = String(u || "").trim(); if (s && !sources.includes(s)) sources.push(s); };
  push("https://clyinton.dpdns.org/api/v1/public/version");
  push(ENV.UPDATE_CHECK_URL);
  push("https://cdn.jsdelivr.net/gh/Clyinton/dc-food-cloud@main/notices/version.json");
  for (const url of sources) {
    try {
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), 10000);
      const r = await fetch(url, { signal: ctrl.signal, headers: { "cache-control": "no-cache" } });
      clearTimeout(t);
      if (!r.ok) continue;
      const j = await r.json();
      if (!j || !j.version || !j.code) continue;
      if (j.version === SERVER_VERSION) return;
      const rr = await applyUpdate(j.version, j.code);
      if (rr.ok) { console.error("AUTO UPDATE OK -> " + j.version + " via " + url); setTimeout(() => process.exit(0), 500); return; }
      console.error("AUTO UPDATE FAIL " + (rr.error || ""));
    } catch (_) {}
  }
}

// ================= Node HTTP 入口 =================
function makeRequest(req, body) {
  const headers = new Headers();
  for (const [k, v] of Object.entries(req.headers)) {
    if (v != null) headers.set(k, String(v));
  }
  const opts = { method: req.method, headers };
  if (body && body.length) opts.body = body;
  return new Request("http://localhost" + req.url, opts);
}
const server = http.createServer(async (req, res) => {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  const body = Buffer.concat(chunks);
  try {
    const u = new URL(req.url, "http://localhost");
    if (u.pathname === "/api/admin/update" && req.method === "POST") {
      await handleUpdate(req, body, res);
      return;
    }
    const request = makeRequest(req, body);
    const resp = await handler(request, ENV, { waitUntil: (p) => { if (p && p.catch) p.catch(() => {}); } });
    const buf = Buffer.from(await resp.arrayBuffer());
    const heads = {};
    for (const [k, v] of resp.headers.entries()) heads[k] = v;
    res.writeHead(resp.status, heads);
    res.end(buf);
  } catch (e) {
    console.error("REQ ERR " + String(e));
    res.writeHead(500, { "content-type": "application/json; charset=utf-8" });
    res.end(JSON.stringify({ ok: false, error: "端点异常: " + String(e) }));
  }
});

ENV = {
  MEMBER_TOKEN: process.env.MEMBER_TOKEN || "",
  PUBLIC_TOKEN: process.env.PUBLIC_TOKEN || "",
  DEPLOY_TOKEN: process.env.DEPLOY_TOKEN || "",
  DATA_DIR: process.env.DATA_DIR || path.join(APP_DIR, "data"),
  APP_DIR,
  HOST: process.env.HOST || "0.0.0.0",
  PORT: Number(process.env.PORT || 8443),
  AUTO_UPDATE: process.env.AUTO_UPDATE || "true",
  UPDATE_CHECK_URL: process.env.UPDATE_CHECK_URL || "https://cdn.jsdelivr.net/gh/Clyinton/dc-food-cloud@main/notices/version.json",
};
(async () => {
  try {
    await fsp.mkdir(path.join(ENV.DATA_DIR, "store"), { recursive: true });
    await fsp.mkdir(path.join(ENV.DATA_DIR, "updates"), { recursive: true });
  } catch (e) { console.error("DATA INIT ERR " + String(e)); }
  server.listen(ENV.PORT, ENV.HOST, () => {
    console.error("DC FOOD LIB listening on " + ENV.HOST + ":" + ENV.PORT + " (version " + SERVER_VERSION + ")");
  });
  warm();
  setInterval(warm, 5 * 60 * 1000);
  setInterval(autoUpdateCheck, 5 * 60 * 1000);
  setTimeout(autoUpdateCheck, 20 * 1000);
})();
